with web_events_by_session as (select session_id, round((100 * sum(case when event_type = 'purchase' then 1 else 0 end)) / count(*), 1) as pct_purchase from web_events group by session_id) select s.id, s.started_at, webs.pct_purchase from sessions s left join web_events_by_session webs on s.id = webs.session_id where webs.pct_purchase > 40 order by started_at asc;
